1: import { forceStopContainer as dockerForceStopContainer } from './dockerUtils.ts';
2: import { logger } from './logger.ts';
3: 
4: // Registry for active sandbox containers: Map<containerId, creationTimestamp>
5: export const activeSandboxContainers = new Map<string, number>();
6: 
7: /**
8:  * Starts the periodic scavenger task to clean up timed-out containers.
9:  * @param containerTimeoutMilliseconds The maximum allowed age for a container in milliseconds.
10:  * @param containerTimeoutSeconds The timeout in seconds (for logging).
11:  * @param checkIntervalMilliseconds How often the scavenger should check (defaults to 60000ms).
12:  * @returns The interval handle returned by setInterval.
13:  */
14: export function startScavenger(
15:   containerTimeoutMilliseconds: number,
16:   containerTimeoutSeconds: number,
17:   checkIntervalMilliseconds = 60 * 1000
18: ): NodeJS.Timeout {
19:   logger.info(
20:     `Starting container scavenger. Timeout: ${containerTimeoutSeconds}s, Check Interval: ${checkIntervalMilliseconds / 1000}s`
21:   );
22: 
23:   const scavengerInterval = setInterval(() => {
24:     const now = Date.now();
25:     if (activeSandboxContainers.size > 0) {
26:       logger.debug(
27:         `Checking ${activeSandboxContainers.size} active containers for timeout (${containerTimeoutSeconds}s)...`
28:       );
29:     }
30:     for (const [
31:       containerId,
32:       creationTimestamp,
33:     ] of activeSandboxContainers.entries()) {
34:       if (now - creationTimestamp > containerTimeoutMilliseconds) {
35:         logger.warning(
36:           `Container ${containerId} timed out (created at ${new Date(creationTimestamp).toISOString()}). Forcing removal.`
37:         );
38: 
39:         dockerForceStopContainer(containerId)
40:           .then(() => {
41:             // Remove from registry AFTER docker command attempt
42:             activeSandboxContainers.delete(containerId);
43:             logger.info(`Removed container ${containerId} from registry.`);
44:           })
45:           .catch((error) => {
46:             // Log error from force stop attempt but continue scavenger
47:             logger.error(`Error during forced stop of ${containerId}`, error);
48:             // Still attempt to remove from registry if Docker failed
49:             activeSandboxContainers.delete(containerId);
50:             logger.info(
51:               `Removed container ${containerId} from registry after error.`
52:             );
53:           });
54:       }
55:     }
56:   }, checkIntervalMilliseconds);
57: 
58:   return scavengerInterval;
59: }
60: 
61: /**
62:  * Attempts to stop and remove all containers currently listed in the
63:  * activeSandboxContainers registry.
64:  * Should be called during graceful shutdown.
65:  */
66: export async function cleanActiveContainers(): Promise<void> {
67:   const containersToClean = Array.from(activeSandboxContainers.keys());
68: 
69:   if (containersToClean.length === 0) {
70:     logger.info('[Shutdown Cleanup] No active containers to clean up.');
71:     return;
72:   }
73: 
74:   logger.info(
75:     `[Shutdown Cleanup] Cleaning up ${containersToClean.length} active containers...`
76:   );
77: 
78:   const cleanupPromises = containersToClean.map(async (id) => {
79:     try {
80:       await dockerForceStopContainer(id); // Attempt to stop/remove via Docker
81:     } catch (error) {
82:       // Log error but continue, registry removal happens regardless
83:       logger.error(`[Shutdown Cleanup] Error stopping container ${id}`, error);
84:     } finally {
85:       activeSandboxContainers.delete(id); // Always remove from registry
86:       logger.info(`[Shutdown Cleanup] Removed container ${id} from registry.`);
87:     }
88:   });
89: 
90:   const results = await Promise.allSettled(cleanupPromises);
91:   logger.info('[Shutdown Cleanup] Container cleanup finished.');
92: 
93:   results.forEach((result, index) => {
94:     if (result.status === 'rejected') {
95:       logger.error(
96:         `[Shutdown Cleanup] Promise for container ${containersToClean[index]} rejected`,
97:         result.reason
98:       );
99:     }
100:   });
101: }

1: #!/usr/bin/env node
2: 
3: import {
4:   McpServer,
5:   ResourceTemplate,
6: } from '@modelcontextprotocol/sdk/server/mcp.js';
7: import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
8: import { randomUUID } from 'crypto';
9: import initializeSandbox, {
10:   argSchema as initializeSchema,
11:   setServerRunId,
12: } from './tools/initialize.ts';
13: import execInSandbox, { argSchema as execSchema } from './tools/exec.ts';
14: import runJs, { argSchema as runJsSchema } from './tools/runJs.ts';
15: import stopSandbox, { argSchema as stopSchema } from './tools/stop.ts';
16: import runJsEphemeral, {
17:   argSchema as ephemeralSchema,
18: } from './tools/runJsEphemeral.ts';
19: import mime from 'mime-types';
20: import fs from 'fs/promises';
21: import { z } from 'zod';
22: import { getConfig } from './config.ts';
23: import { startScavenger, cleanActiveContainers } from './containerUtils.ts';
24: import { setServerInstance, logger } from './logger.ts';
25: import getDependencyTypes, {
26:   argSchema as getDependencyTypesSchema,
27: } from './tools/getDependencyTypes.ts';
28: import searchNpmPackages, {
29:   SearchNpmPackagesToolSchema,
30: } from './tools/searchNpmPackages.ts';
31: 
32: import packageJson from '../package.json' with { type: 'json' };
33: 
34: export const serverRunId = randomUUID();
35: setServerRunId(serverRunId);
36: 
37: // Create the server with logging capability enabled
38: const server = new McpServer(
39:   {
40:     name: packageJson.name,
41:     version: packageJson.version,
42:     description: packageJson.description,
43:   },
44:   {
45:     capabilities: {
46:       logging: {},
47:       tools: {},
48:     },
49:   }
50: );
51: 
52: // Set the server instance for logging
53: setServerInstance(server);
54: 
55: // Configure server tools and resources
56: server.tool(
57:   'sandbox_initialize',
58:   'Start a new isolated Docker container running Node.js. Used to set up a sandbox session for multiple commands and scripts.',
59:   initializeSchema,
60:   initializeSandbox
61: );
62: 
63: server.tool(
64:   'sandbox_exec',
65:   'Execute one or more shell commands inside a running sandbox container. Requires a sandbox initialized beforehand.',
66:   execSchema,
67:   execInSandbox
68: );
69: 
70: server.tool(
71:   'run_js',
72:   `Install npm dependencies and run JavaScript code inside a running sandbox container.
73:   After running, you must manually stop the sandbox to free resources.
74:   The code must be valid ESModules (import/export syntax). Best for complex workflows where you want to reuse the environment across multiple executions.
75:   When reading and writing from the Node.js processes, you always need to read from and write to the "./files" directory to ensure persistence on the mounted volume.`,
76:   runJsSchema,
77:   runJs
78: );
79: 
80: server.tool(
81:   'sandbox_stop',
82:   'Terminate and remove a running sandbox container. Should be called after finishing work in a sandbox initialized with sandbox_initialize.',
83:   stopSchema,
84:   stopSandbox
85: );
86: 
87: server.tool(
88:   'run_js_ephemeral',
89:   `Run a JavaScript snippet in a temporary disposable container with optional npm dependencies, then automatically clean up. 
90:   The code must be valid ESModules (import/export syntax). Ideal for simple one-shot executions without maintaining a sandbox or managing cleanup manually.
91:   When reading and writing from the Node.js processes, you always need to read from and write to the "./files" directory to ensure persistence on the mounted volume.
92:   This includes images (e.g., PNG, JPEG) and other files (e.g., text, JSON, binaries).
93: 
94:   Example:
95:   \`\`\`js
96:   import fs from "fs/promises";
97:   await fs.writeFile("./files/hello.txt", "Hello world!");
98:   console.log("Saved ./files/hello.txt");
99:   \`\`\`
100: `,
101:   ephemeralSchema,
102:   runJsEphemeral
103: );
104: 
105: server.tool(
106:   'get_dependency_types',
107:   `
108:   Given an array of npm package names (and optional versions), 
109:   fetch whether each package ships its own TypeScript definitions 
110:   or has a corresponding @types/… package, and return the raw .d.ts text.
111:   
112:   Useful whenwhen you're about to run a Node.js script against an unfamiliar dependency 
113:   and want to inspect what APIs and types it exposes.
114:   `,
115:   getDependencyTypesSchema,
116:   getDependencyTypes
117: );
118: 
119: server.tool(
120:   'search_npm_packages',
121:   'Search for npm packages by a search term and get their name, description, and a README snippet.',
122:   SearchNpmPackagesToolSchema.shape,
123:   searchNpmPackages
124: );
125: 
126: server.resource(
127:   'file',
128:   new ResourceTemplate('file://{+filepath}', { list: undefined }),
129:   async (uri) => {
130:     const filepath = new URL(uri).pathname;
131:     const data = await fs.readFile(filepath);
132:     const mimeType = mime.lookup(filepath) || 'application/octet-stream';
133:     return {
134:       contents: [
135:         {
136:           uri: uri.toString(),
137:           mimeType,
138:           blob: data.toString('base64'),
139:         },
140:       ],
141:     };
142:   }
143: );
144: 
145: server.prompt('run-node-js-script', { prompt: z.string() }, ({ prompt }) => ({
146:   messages: [
147:     {
148:       role: 'user',
149:       content: {
150:         type: 'text',
151:         text:
152:           `Here is my prompt:\n\n${prompt}\n\n` +
153:           `Follow modern Node.js best practices:\n` +
154:           // I've noticed that gpt4o-mini tends to use CommonJS
155:           `- Use ECMAScript Modules (ESM) syntax (import/export), avoid CommonJS (require/module.exports)\n` +
156:           // gpt4o-mini tends to try to install node-fetch
157:           `- Use native fetch, avoid node-fetch or axios unless absolutely necessary or requested\n` +
158:           `- Prefer top-level await in ES modules when appropriate\n` +
159:           `- Use async/await consistently for asynchronous code, avoid mixing with .then/.catch\n` +
160:           `- Avoid callback-style code in favor of Promises and async/await\n` +
161:           `- Avoid unnecessary dependencies if a native API is available\n` +
162:           `Please write and run a Node.js script.`,
163:       },
164:     },
165:   ],
166: }));
167: 
168: const scavengerIntervalHandle = startScavenger(
169:   getConfig().containerTimeoutMilliseconds,
170:   getConfig().containerTimeoutSeconds
171: );
172: 
173: async function gracefulShutdown(signal: string) {
174:   logger.info(`Received ${signal}. Starting graceful shutdown...`);
175: 
176:   clearInterval(scavengerIntervalHandle);
177:   logger.info('Stopped container scavenger.');
178: 
179:   await cleanActiveContainers();
180: 
181:   setTimeout(() => {
182:     logger.info('Exiting.');
183:     process.exit(0);
184:   }, 500);
185: }
186: 
187: process.on('SIGINT', () => gracefulShutdown('SIGINT'));
188: process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
189: process.on('SIGUSR2', () => gracefulShutdown('SIGUSR2'));
190: 
191: // Set up the transport
192: const transport = new StdioServerTransport();
193: 
194: // Connect the server to start receiving and sending messages
195: logger.info('Initializing server...');
196: await server.connect(transport);
197: logger.info('Server started and connected successfully');
198: logger.info(
199:   `Container timeout set to: ${getConfig().containerTimeoutSeconds} seconds (${getConfig().containerTimeoutMilliseconds}ms)`
200: );

1: import { z } from 'zod';
2: import { execSync } from 'node:child_process';
3: import { randomUUID } from 'node:crypto';
4: import { type McpResponse, textContent } from '../types.ts';
5: import {
6:   DEFAULT_NODE_IMAGE,
7:   DOCKER_NOT_RUNNING_ERROR,
8:   isDockerRunning,
9:   computeResourceLimits,
10: } from '../utils.ts';
11: import { getMountFlag } from '../runUtils.ts';
12: import { activeSandboxContainers } from '../containerUtils.ts';
13: import { logger } from '../logger.ts';
14: 
15: // Instead of importing serverRunId directly, we'll have a variable that gets set
16: let serverRunId = 'unknown';
17: 
18: // Function to set the serverRunId from the server.ts file
19: export function setServerRunId(id: string) {
20:   serverRunId = id;
21: }
22: 
23: export const argSchema = {
24:   image: z.string().optional(),
25:   port: z
26:     .number()
27:     .optional()
28:     .describe('If set, maps this container port to the host'),
29: };
30: 
31: export default async function initializeSandbox({
32:   image = DEFAULT_NODE_IMAGE,
33:   port,
34: }: {
35:   image?: string;
36:   port?: number;
37: }): Promise<McpResponse> {
38:   if (!isDockerRunning()) {
39:     return {
40:       content: [textContent(DOCKER_NOT_RUNNING_ERROR)],
41:     };
42:   }
43: 
44:   const containerId = `js-sbx-${randomUUID()}`;
45:   const creationTimestamp = Date.now();
46: 
47:   const portOption = port ? `-p ${port}:${port}` : `--network host`; // prefer --network host if no explicit port mapping
48: 
49:   // Construct labels
50:   const labels = [
51:     `mcp-sandbox=true`,
52:     `mcp-server-run-id=${serverRunId}`,
53:     `mcp-creation-timestamp=${creationTimestamp}`,
54:   ];
55:   const labelArgs = labels.map((label) => `--label "${label}"`).join(' ');
56:   const { memFlag, cpuFlag } = computeResourceLimits(image);
57:   const mountFlag = getMountFlag();
58: 
59:   try {
60:     execSync(
61:       `docker run -d ${portOption} ${memFlag} ${cpuFlag} ` +
62:       `--workdir /workspace ${mountFlag} ` +
63:       `${labelArgs} ` + // Add labels here
64:       `--name ${containerId} ${image} tail -f /dev/null`
65:     );
66: 
67:     // Register the container only after successful creation
68:     activeSandboxContainers.set(containerId, creationTimestamp);
69:     logger.info(`Registered container ${containerId}`);
70: 
71:     return {
72:       content: [textContent(containerId)],
73:     };
74:   } catch (error) {
75:     logger.error(`Failed to initialize container ${containerId}`, error);
76:     // Ensure partial cleanup if execSync fails after container might be created but before registration
77:     try {
78:       execSync(`docker rm -f ${containerId}`);
79:     } catch (cleanupError: unknown) {
80:       // Ignore cleanup errors - log it just in case
81:       logger.warning(
82:         `Ignoring error during cleanup attempt for ${containerId}: ${String(cleanupError)}`
83:       );
84:     }
85:     return {
86:       content: [
87:         textContent(
88:           `Failed to initialize sandbox container: ${error instanceof Error ? error.message : String(error)}`
89:         ),
90:       ],
91:     };
92:   }
93: }

1: import { z } from 'zod';
2: import { execSync } from 'node:child_process';
3: import { type McpResponse, textContent } from '../types.ts';
4: import { DOCKER_NOT_RUNNING_ERROR, isDockerRunning } from '../utils.ts';
5: import { activeSandboxContainers } from '../containerUtils.ts';
6: 
7: export const argSchema = { container_id: z.string() };
8: 
9: export default async function stopSandbox({
10:   container_id,
11: }: {
12:   container_id: string;
13: }): Promise<McpResponse> {
14:   if (!isDockerRunning()) {
15:     return {
16:       content: [textContent(DOCKER_NOT_RUNNING_ERROR)],
17:     };
18:   }
19: 
20:   try {
21:     // Directly use execSync for removing the container as expected by the test
22:     execSync(`docker rm -f ${container_id}`);
23:     activeSandboxContainers.delete(container_id);
24:     // console.log(
25:     //   `[stopSandbox] Removed container ${container_id} from registry.`
26:     // );
27: 
28:     return {
29:       content: [textContent(`Container ${container_id} removed.`)],
30:     };
31:   } catch (error) {
32:     // Handle any errors that occur during container removal
33:     const errorMessage = error instanceof Error ? error.message : String(error);
34:     console.error(
35:       `[stopSandbox] Error removing container ${container_id}: ${errorMessage}`
36:     );
37: 
38:     // Still remove from our registry even if Docker command failed
39:     activeSandboxContainers.delete(container_id);
40: 
41:     return {
42:       content: [
43:         textContent(
44:           `Error removing container ${container_id}: ${errorMessage}`
45:         ),
46:       ],
47:     };
48:   }
49: }

1: import { describe, it, expect, beforeAll, afterAll } from 'vitest';
2: import initializeSandbox from '../src/tools/initialize.ts';
3: import execInSandbox from '../src/tools/exec.ts';
4: import stopSandbox from '../src/tools/stop.ts';
5: import * as utils from '../src/utils.ts';
6: import { vi } from 'vitest';
7: 
8: let containerId: string;
9: 
10: beforeAll(async () => {
11:   const result = await initializeSandbox({});
12:   const content = result.content[0];
13:   if (content.type !== 'text') throw new Error('Unexpected content type');
14:   containerId = content.text;
15: });
16: 
17: afterAll(async () => {
18:   await stopSandbox({ container_id: containerId });
19: });
20: 
21: describe('execInSandbox', () => {
22:   it('should return an error if Docker is not running', async () => {
23:     vi.spyOn(utils, 'isDockerRunning').mockReturnValue(false);
24: 
25:     const result = await initializeSandbox({});
26:     expect(result).toEqual({
27:       content: [
28:         {
29:           type: 'text',
30:           text: 'Error: Docker is not running. Please start Docker and try again.',
31:         },
32:       ],
33:     });
34: 
35:     vi.restoreAllMocks();
36:   });
37:   it('should execute a single command and return its output', async () => {
38:     const result = await execInSandbox({
39:       container_id: containerId,
40:       commands: ['echo Hello'],
41:     });
42: 
43:     expect(result.content[0].type).toBe('text');
44:     if (result.content[0].type === 'text') {
45:       expect(result.content[0].text.trim()).toBe('Hello');
46:     } else {
47:       throw new Error('Unexpected content type');
48:     }
49:   });
50: 
51:   it('should execute multiple commands and join their outputs', async () => {
52:     const result = await execInSandbox({
53:       container_id: containerId,
54:       commands: ['echo First', 'echo Second'],
55:     });
56: 
57:     let output: string[] = [];
58:     if (result.content[0].type === 'text') {
59:       output = result.content[0].text.trim().split('\n');
60:       expect(output).toEqual(['First', '', 'Second']);
61:     } else {
62:       throw new Error('Unexpected content type');
63:     }
64:   });
65: 
66:   it('should handle command with special characters', async () => {
67:     const result = await execInSandbox({
68:       container_id: containerId,
69:       commands: ['echo "Special: $HOME"'],
70:     });
71: 
72:     if (result.content[0].type === 'text') {
73:       expect(result.content[0].text.trim()).toContain('Special:');
74:     } else {
75:       throw new Error('Unexpected content type');
76:     }
77:   });
78: });

1: import { describe, it, expect, beforeEach, afterEach } from 'vitest';
2: import * as tmp from 'tmp';
3: import { execSync } from 'node:child_process';
4: import runJs from '../src/tools/runJs.ts';
5: import { DEFAULT_NODE_IMAGE } from '../src/utils.ts';
6: 
7: function startSandboxContainer(): string {
8:   return execSync(
9:     `docker run -d --network host --memory 512m --cpus 1 --workdir /workspace ${DEFAULT_NODE_IMAGE} tail -f /dev/null`,
10:     { encoding: 'utf-8' }
11:   ).trim();
12: }
13: let tmpDir: tmp.DirResult;
14: 
15: function stopSandboxContainer(containerId: string) {
16:   execSync(`docker rm -f ${containerId}`);
17: }
18: 
19: describe('runJs npm install benchmarking', () => {
20:   beforeEach(() => {
21:     tmpDir = tmp.dirSync({ unsafeCleanup: true });
22:     process.env.FILES_DIR = tmpDir.name;
23:   });
24: 
25:   afterEach(() => {
26:     tmpDir.removeCallback();
27:     delete process.env.FILES_DIR;
28:   });
29: 
30:   it('should install dependency faster on second run due to caching', async () => {
31:     const containerId = startSandboxContainer();
32: 
33:     try {
34:       const dependency = { name: 'lodash', version: '^4.17.21' };
35: 
36:       // First run: benchmark install
37:       const result1 = await runJs({
38:         container_id: containerId,
39:         code: "console.log('Hello')",
40:         dependencies: [dependency],
41:       });
42: 
43:       const telemetryItem1 = result1.content.find(
44:         (c) => c.type === 'text' && c.text.startsWith('Telemetry:')
45:       );
46:       expect(telemetryItem1).toBeDefined();
47:       const telemetry1 = JSON.parse(
48:         (telemetryItem1 && telemetryItem1.type === 'text'
49:           ? telemetryItem1.text
50:           : ''
51:         ).replace('Telemetry:\n', '')
52:       );
53:       const installTimeMs1 = telemetry1.installTimeMs;
54: 
55:       // Second run: same install again, expect faster
56:       const result2 = await runJs({
57:         container_id: containerId,
58:         code: "console.log('Hello')",
59:         dependencies: [dependency],
60:       });
61: 
62:       const telemetryItem2 = result2.content.find(
63:         (c) => c.type === 'text' && c.text.startsWith('Telemetry:')
64:       );
65:       expect(telemetryItem2).toBeDefined();
66:       const telemetry2 = JSON.parse(
67:         (telemetryItem2 && telemetryItem2.type === 'text'
68:           ? telemetryItem2.text
69:           : ''
70:         ).replace('Telemetry:\n', '')
71:       );
72:       const installTimeMs2 = telemetry2.installTimeMs;
73:       // Assert that second install is faster
74:       try {
75:         expect(installTimeMs2).toBeLessThan(installTimeMs1);
76:       } catch (error) {
77:         console.error('Error in assertion:', error);
78:         console.log(`First install time: ${installTimeMs1}ms`);
79:         console.log(`Second install time: ${installTimeMs2}ms`);
80:         throw error; // Re-throw the error to fail the test
81:       }
82:     } finally {
83:       stopSandboxContainer(containerId);
84:     }
85:   }, 20_000);
86: });

1: import { describe, it, expect, beforeEach, afterEach } from 'vitest';
2: import * as tmp from 'tmp';
3: import { z } from 'zod';
4: import runJsEphemeral, { argSchema } from '../src/tools/runJsEphemeral.ts';
5: import { DEFAULT_NODE_IMAGE } from '../src/utils.ts';
6: import { describeIfLocal } from './utils.ts';
7: import type {
8:   McpContentImage,
9:   McpContentResource,
10:   McpContentText,
11:   McpContentTextResource,
12: } from '../src/types.ts';
13: 
14: let tmpDir: tmp.DirResult;
15: 
16: describe('runJsEphemeral', () => {
17:   beforeEach(() => {
18:     tmpDir = tmp.dirSync({ unsafeCleanup: true });
19:     process.env.FILES_DIR = tmpDir.name;
20:   });
21: 
22:   afterEach(() => {
23:     tmpDir.removeCallback();
24:     delete process.env.FILES_DIR;
25:   });
26:   describe('argSchema', () => {
27:     it('should use default values for image and dependencies', () => {
28:       const parsed = z.object(argSchema).parse({ code: 'console.log(1);' });
29:       expect(parsed.image).toBe(DEFAULT_NODE_IMAGE);
30:       expect(parsed.dependencies).toEqual([]);
31:       expect(parsed.code).toBe('console.log(1);');
32:     });
33: 
34:     it('should accept valid custom image and dependencies', () => {
35:       const input = {
36:         image: DEFAULT_NODE_IMAGE,
37:         dependencies: [
38:           { name: 'lodash', version: '^4.17.21' },
39:           { name: 'axios', version: '^1.0.0' },
40:         ],
41:         code: "console.log('hi');",
42:       };
43:       const parsed = z.object(argSchema).parse(input);
44:       expect(parsed.image).toBe(DEFAULT_NODE_IMAGE);
45:       expect(parsed.dependencies.length).toBe(2);
46:       expect(parsed.dependencies[0]).toEqual({
47:         name: 'lodash',
48:         version: '^4.17.21',
49:       });
50:       expect(parsed.code).toBe("console.log('hi');");
